            if (bytes.length > 65536 || !hash(bytes).equals(MANIFEST)) throw denied();
            var values = new LinkedHashMap<String, JsonNode>();
            for (var fixture : GeminiLlmProviderAdapter.JSON.readTree(bytes).path("fixtures")) {
